import { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { API } from "../api/api";
import Navbar from "../components/Navbar";

export default function PollPage() {
  const { id } = useParams();
  const nav = useNavigate();

  const [poll, setPoll] = useState(null);
  const [voted, setVoted] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchPoll();
  }, []);

  const fetchPoll = async () => {
    try {
      const res = await API.get(`/polls/${id}`);
      setPoll(res.data);
    } catch (err) {
      console.log(err);
    } finally {
      setLoading(false);
    }
  };

  const vote = async (index) => {
    try {
      await API.post(`/polls/${id}/vote`, {
        optionIndex: index
      });

      setVoted(true);
      fetchPoll(); // refresh results
    } catch (err) {
      alert("Vote failed");
    }
  };

  if (loading) return <p style={{ color: "white" }}>Loading...</p>;
  if (!poll) return <p style={{ color: "white" }}>Poll not found</p>;

  return (
    <>
      <Navbar />

      <style>{`
        .page {
          min-height: 100vh;
          display: flex;
          justify-content: center;
          align-items: center;
          background: radial-gradient(circle at top,#1e3a8a,#0b1220 60%);
          color: white;
          padding: 20px;
        }

        .card {
          width: 450px;
          background: #111827;
          padding: 25px;
          border-radius: 18px;
          box-shadow: 0 15px 40px rgba(0,0,0,0.6);
        }

        .question {
          font-size: 20px;
          font-weight: 700;
          margin-bottom: 20px;
          text-align: center;
        }

        .option {
          background: #1f2937;
          padding: 12px;
          margin: 10px 0;
          border-radius: 10px;
          cursor: pointer;
          transition: 0.2s;
          display: flex;
          justify-content: space-between;
        }

        .option:hover {
          background: #374151;
          transform: scale(1.02);
        }

        .bar {
          height: 6px;
          background: #22c55e;
          border-radius: 10px;
          margin-top: 5px;
        }

        .back {
          width: 100%;
          margin-top: 15px;
          padding: 10px;
          border: none;
          border-radius: 10px;
          background: #3b82f6;
          color: white;
          cursor: pointer;
        }

        .voted {
          text-align: center;
          color: #22c55e;
          margin-bottom: 10px;
        }
      `}</style>

      <div className="page">
        <div className="card">

          <div className="question">{poll.question}</div>

          {voted && <div className="voted">✔ You voted</div>}

          {poll.options.map((opt, i) => {
            const totalVotes = poll.options.reduce((a, b) => a + b.votes, 0);
            const percent = totalVotes
              ? Math.round((opt.votes / totalVotes) * 100)
              : 0;

            return (
              <div key={i}>
                <div
                  className="option"
                  onClick={() => !voted && vote(i)}
                  style={{ opacity: voted ? 0.8 : 1 }}
                >
                  <span>{opt.text}</span>
                  <span>{opt.votes} votes</span>
                </div>

                {/* progress bar */}
                <div
                  className="bar"
                  style={{ width: `${percent}%` }}
                ></div>
              </div>
            );
          })}

          <button className="back" onClick={() => nav("/home")}>
            ← Back to Home
          </button>

        </div>
      </div>
    </>
  );
}
